class Solution {
  public int uniqueXorTriplets(int[] nums) {
    final int SIZE = 2048;
    boolean[] present = new boolean[SIZE];
    for (int x : nums) present[x] = true;
    int[] values = new int[nums.length];
    int count = 0;
    for (int v = 0; v < SIZE; v++) if (present[v]) values[count++] = v;
    boolean[] pairs = new boolean[SIZE]; // xor of two elements (the same element may repeat)
    for (int i = 0; i < count; i++) {
      for (int j = i; j < count; j++) pairs[values[i] ^ values[j]] = true;
    }
    boolean[] triples = new boolean[SIZE];
    for (int p = 0; p < SIZE; p++) {
      if (!pairs[p]) continue;
      for (int i = 0; i < count; i++) triples[p ^ values[i]] = true;
    }
    int result = 0;
    for (boolean t : triples) if (t) result++;
    return result;
  }
}
